const input = $json.body ?? $json;
const text = (v) => v === null || v === undefined ? '' : String(v).trim();
const bool = (v) => typeof v === 'boolean' ? v : ['true','1','yes','on'].includes(text(v).toLowerCase());

const clinic_name=text(input.clinic_name);
const question=text(input.question);
const mobile=text(input.mobile);
const specialty_hint=text(input.specialty_hint||'general').toLowerCase();
const service_name=text(input.service_name);
const session_id=Number(input.session_id??0);
const message_id=Number(input.message_id??0);
const clinical_intake_case_id=Number(input.clinical_intake_case_id??0);
const webhook_base_url=text(input.webhook_base_url||'http://n8n:5678/webhook').replace(/\/+$/,'');
const model_provider=text(input.model_provider||'openai').toLowerCase();
const model_name=text(input.model_name||'gpt-5-mini');
const confirm_answer=bool(input.confirm_answer);
const errors=[];

if(!clinic_name) errors.push({field:'clinic_name',message:'نام کلینیک الزامی است.'});
if(!question) errors.push({field:'question',message:'سؤال الزامی است.'});
if(question.length>8000) errors.push({field:'question',message:'سؤال بیش از حد طولانی است.'});
if(mobile&&!/^\+?[0-9]{8,15}$/.test(mobile)) errors.push({field:'mobile',message:'شماره موبایل معتبر نیست.'});
for(const [f,v] of Object.entries({session_id,message_id,clinical_intake_case_id})){
  if(!Number.isInteger(v)||v<0) errors.push({field:f,message:`${f} معتبر نیست.`});
}
if(!/^https?:\/\/.+/i.test(webhook_base_url)) errors.push({field:'webhook_base_url',message:'آدرس Webhook معتبر نیست.'});
if(!model_provider||!model_name) errors.push({field:'model',message:'مدل الزامی است.'});
if(confirm_answer!==true) errors.push({field:'confirm_answer',message:'پردازش باید تأیید شود.'});

return [{json:{
  clinic_name,question,mobile,specialty_hint,service_name,session_id,message_id,
  clinical_intake_case_id,webhook_base_url,model_provider,model_name,
  analyzer_prompt_version:'clinical-query-analyzer-v1',
  answer_prompt_version:'clinical-grounded-answer-v1',
  confirm_answer,validation_status:errors.length?'invalid':'valid',errors
}}];

const i=$json;
return [{json:{...i,analyzer_prompt:[
  'PATIENT_QUESTION:',i.question,'',
  'HINTS:',JSON.stringify({
    clinic_name:i.clinic_name,
    specialty_hint:i.specialty_hint,
    service_name:i.service_name||null,
    clinical_intake_case_id:i.clinical_intake_case_id||null
  }),'',
  'Return only the structured output required by the schema.'
].join('\n')}}];

const envelope=$json??{};
let p=envelope.output??envelope;
if(typeof p==='string'){const m=p.match(/\{[\s\S]*\}/);p=JSON.parse(m?m[0]:p);}
if(p&&typeof p==='object'&&p.output&&typeof p.output==='object') p=p.output;
const i=$('Build Clinical Query Analyzer Prompt').first().json;
let flags=Array.isArray(p.risk_flags)?[...new Set(p.risk_flags.map(x=>String(x||'').trim()).filter(Boolean))]:[];
if(flags.length>1) flags=flags.filter(x=>x!=='none');
const urgentFlags=['breathing_difficulty','loss_of_consciousness','seizure','chest_pain','possible_overdose','severe_bleeding','self_harm_or_violence','pregnancy_emergency_concern','new_neurological_deficit'];
const deterministicUrgent=flags.some(x=>urgentFlags.includes(x));
return [{json:{
  ...i,
  normalized_query:String(p.normalized_query||i.question).trim(),
  specialty:String(p.specialty||i.specialty_hint||'general').trim().toLowerCase(),
  topic:p.topic==null?null:String(p.topic).trim()||null,
  keywords:Array.isArray(p.keywords)?p.keywords.map(x=>String(x||'').trim()).filter(Boolean).slice(0,12):[],
  risk_flags:flags,
  urgent:Boolean(p.urgent||deterministicUrgent),
  requires_human:Boolean(p.requires_human||deterministicUrgent),
  retrieval_allowed:Boolean(p.retrieval_allowed!==false&&!deterministicUrgent),
  analysis_summary:String(p.analysis_summary||'').slice(0,1000)
}}];

const retrieval=$json;
const analysis=$('Normalize Clinical Query Analysis').first().json;
const context=Array.isArray(retrieval.retrieved_context)?retrieval.retrieved_context:[];
const available=context.map(x=>({
  result_type:x.result_type,result_id:x.result_id,document_id:x.document_id,
  title:x.title,page_start:x.page_start,page_end:x.page_end,score:x.score,
  requires_human_confirmation:x.requires_human_confirmation,
  safety_category:x.safety_category
}));
const prompt=[
  'PATIENT_QUESTION:',analysis.question,'',
  'RISK_ANALYSIS:',JSON.stringify({risk_flags:analysis.risk_flags,analysis_summary:analysis.analysis_summary}),'',
  'RETRIEVED_SOURCES:',JSON.stringify(context),'',
  'Answer only from retrieved sources. If sources are absent, weak, conflicting, human-only, or require confirmation, do not invent an answer.',
  'Do not diagnose, prescribe, or change medication dosage.',
  'Return only the structured output required by the schema.'
].join('\n');
return [{json:{
  ...analysis,
  clinical_knowledge_query_id:retrieval.clinical_knowledge_query_id??null,
  retrieved_context:context,
  available_citations:available,
  top_score:Number(retrieval.top_score??0),
  answer_prompt:prompt
}}];

const envelope=$json??{};
let p=envelope.output??envelope;
if(typeof p==='string'){const m=p.match(/\{[\s\S]*\}/);p=JSON.parse(m?m[0]:p);}
if(p&&typeof p==='object'&&p.output&&typeof p.output==='object') p=p.output;
const c=$('Prepare Grounded Answer Prompt').first().json;
const available=new Map((c.available_citations||[]).map(x=>[Number(x.result_id),x]));
const used=Array.isArray(p.used_result_ids)?[...new Set(p.used_result_ids.map(Number).filter(x=>Number.isInteger(x)&&available.has(x)))]:[];
const citations=used.map(x=>available.get(x)).filter(Boolean);
const forced=citations.some(x=>x.requires_human_confirmation===true||x.safety_category==='human_only');
const hasContext=Array.isArray(c.retrieved_context)&&c.retrieved_context.length>0;
let status=p.answer_status||'no_reliable_answer';
let text=String(p.answer_text||'').trim();
let human=Boolean(p.requires_human||forced);
if(!hasContext||used.length===0){
  status='no_reliable_answer';human=true;
  text='برای پاسخ دقیق، منبع تأییدشده کافی در پایگاه دانش کلینیک پیدا نشد و این موضوع باید توسط مسئول یا پزشک کلینیک بررسی شود.';
}
if(forced) status='human_review';
return [{json:{
  success:true,
  result:status==='answered'?'grounded_clinical_answer_created':status==='human_review'?'clinical_answer_requires_human_review':'no_reliable_clinical_answer',
  clinic_name:c.clinic_name,session_id:c.session_id,message_id:c.message_id,
  clinical_intake_case_id:c.clinical_intake_case_id,
  clinical_knowledge_query_id:c.clinical_knowledge_query_id,
  question:c.question,normalized_query:c.normalized_query,specialty:c.specialty,
  risk_flags:c.risk_flags,urgent:false,answer_status:status,answer_text:text.slice(0,2500),
  used_result_ids:used,citations,citations_json:JSON.stringify(citations),
  requires_human:human,confidence:Math.max(0,Math.min(1,Number(p.confidence??0))),
  reason_summary:String(p.reason_summary||'').slice(0,700),
  model_provider:c.model_provider,model_name:c.model_name,prompt_version:c.answer_prompt_version,
  next_action:human?'human_review':'return_grounded_answer'
}}];

const a=$('Normalize Clinical Query Analysis').first().json;
return [{json:{
  success:false,
  result:$json.result||'clinical_knowledge_retrieval_failed',
  message:'منبع تأییدشده کافی برای پاسخ پیدا نشد.',
  clinic_name:a.clinic_name,session_id:a.session_id,message_id:a.message_id,
  clinical_intake_case_id:a.clinical_intake_case_id,risk_flags:a.risk_flags,
  requires_human:true,urgent:false,answer_status:'no_reliable_answer',
  answer_text:'برای پاسخ دقیق، این موضوع باید توسط مسئول یا پزشک کلینیک بررسی شود.',
  citations:[],next_action:'human_review'
}}];

const urgent = $json;
const source =
  $('Normalize Clinical Query Analysis').first().json;

return [{
  json: {
    urgent_response: urgent,
    handoff_url:
      `${source.webhook_base_url}/clinic/handoff/create`,
    handoff_payload: {
      clinic_name: source.clinic_name,
      session_id: source.session_id,
      message_id: source.message_id,
      mobile: source.mobile || '',
      urgency: 'urgent',
      reason:
        'سؤال تخصصی دارای نشانه‌های خطر فوری شناسایی شد.',
      patient_message: source.question,
      risk_flags: source.risk_flags || [],
      confirm_handoff: true,
    },
  },
}];

const urgent =
  $('Return Urgent Clinical Safety Message').first().json;
const handoff = $json || {};

const handoffCreated =
  handoff.success === true;

return [{
  json: {
    ...urgent,
    handoff_created: handoffCreated,
    handoff_result:
      handoff.result ||
      (
        handoffCreated
          ? 'human_handoff_created'
          : 'human_handoff_creation_failed'
      ),
    handoff_task_id:
      handoff.handoff_task_id ||
      handoff.task_id ||
      null,
    next_action:
      handoffCreated
        ? 'urgent_human_handoff_created'
        : 'urgent_human_handoff_requires_review',
  },
}];

return [{
  json: {
    ...$json,
    handoff_created: false,
    handoff_result:
      'conversation_reference_missing',
    next_action:
      'urgent_human_handoff_requires_conversation_reference',
  },
}];

const answer =
  $('Normalize Grounded Clinical Answer').first().json;
const saved = $json || {};

if (saved.success !== true) {
  return [{
    json: {
      ...answer,
      success: false,
      result:
        saved.result ||
        'clinical_grounded_answer_save_failed',
      save_success: false,
      answer_delivery_allowed: false,
      requires_human: true,
      next_action: 'human_review',
    },
  }];
}

return [{
  json: {
    ...answer,
    success: true,
    save_success: true,
    save_result: saved.result,
    clinical_knowledge_query_id:
      saved.clinical_knowledge_query_id ||
      answer.clinical_knowledge_query_id,
    answer_status:
      saved.answer_status ||
      answer.answer_status,
    answer_text:
      saved.answer_text ||
      answer.answer_text,
    citations:
      saved.citations ||
      answer.citations,
    answer_delivery_allowed: true,
  },
}];
